package config

import (
	"crypto/sha256"
	"encoding/hex"
)

// Fingerprint returns a short, stable identifier for a secret, so that logs can
// show which credential is in effect without revealing it. Comparing it with
// the fingerprint of the intended secret diagnoses "the wrong password was
// loaded" without the password ever appearing in a log:
//
//	printf '%s' "$SECRET" | shasum -a 256 | cut -c1-8
//
// It is a truncated, unsalted SHA-256. That is acceptable only because the
// secrets it is used for are high-entropy (passwords generated by the PBX, API
// keys): a short dictionary password could be recovered from it offline.
func Fingerprint(secret string) string {
	if secret == "" {
		return "(empty)"
	}
	sum := sha256.Sum256([]byte(secret))
	return "sha256:" + hex.EncodeToString(sum[:4])
}
